router_facturas:
"""
Rutas de facturas: /api/facturas  (Requerimientos 7, 8 y 9 del quinto avance)

- POST  /api/facturas                → generar factura desde una venta
- GET   /api/facturas                → consultar facturas con filtros
- GET   /api/facturas/{id}           → consultar una factura
- GET   /api/facturas/{id}/pdf       → descargar la factura en PDF
- PATCH /api/facturas/{id}/estado    → cambiar estado de la factura
"""
from datetime import date, datetime, time

from fastapi import APIRouter, Depends, HTTPException, Query, status
from fastapi.responses import StreamingResponse
from sqlalchemy.orm import Session

from ..database import get_db
from ..models import DetalleFactura, Factura, Usuario, Venta
from ..schemas import FacturaCreate, FacturaEstadoUpdate
from ..security import get_current_user, require_roles
from ..utils.numeracion import generar_numero_factura
from ..utils.reportes import factura_pdf
from ..utils.serializadores import factura_a_dict

router = APIRouter(prefix='/api/facturas', tags=['Facturas'])

ROLES_GESTION = ('administrador', 'empleado')


@router.post('', status_code=status.HTTP_201_CREATED)
def generar_factura(
    body: FacturaCreate,
    db: Session = Depends(get_db),
    _: Usuario = Depends(require_roles(*ROLES_GESTION)),
):
    """Genera la factura de venta a partir de una operación comercial registrada."""
    venta = db.query(Venta).filter(Venta.id == body.venta_id).first()
    if venta is None:
        raise HTTPException(
            status_code=status.HTTP_404_NOT_FOUND,
            detail='La venta indicada no existe.',
        )
    if venta.factura is not None:
        raise HTTPException(
            status_code=status.HTTP_400_BAD_REQUEST,
            detail=f'La venta ya tiene la factura {venta.factura.numero_factura} generada.',
        )
    if venta.estado == 'anulada':
        raise HTTPException(
            status_code=status.HTTP_400_BAD_REQUEST,
            detail='No se puede facturar una venta anulada.',
        )
    if not venta.detalles:
        raise HTTPException(
            status_code=status.HTTP_400_BAD_REQUEST,
            detail='La venta no tiene productos ni servicios registrados.',
        )

    factura = Factura(
        numero_factura=generar_numero_factura(db),
        venta_id=venta.id,
        cliente_id=venta.cliente_id,
        subtotal=venta.subtotal,
        descuento=venta.descuento,
        impuestos=venta.impuestos,
        total=venta.total,
        metodo_pago=body.metodo_pago or venta.metodo_pago,
        estado='emitida' if venta.estado != 'pagada' else 'pagada',
    )
    # La factura congela el detalle con los precios del momento de la venta.
    factura.detalles = [
        DetalleFactura(
            descripcion=d.descripcion,
            cantidad=d.cantidad,
            precio_unitario=d.precio_unitario,
            descuento=d.descuento,
            subtotal=d.subtotal,
        )
        for d in venta.detalles
    ]

    db.add(factura)
    if venta.estado == 'pendiente':
        venta.estado = 'pagada'
    db.commit()
    db.refresh(factura)

    return {
        'message': 'Factura generada exitosamente.',
        'invoice': factura_a_dict(factura),
    }


@router.get('')
def listar_facturas(
    numero_factura: str | None = Query(default=None, max_length=20),
    cliente_id: int | None = Query(default=None),
    fecha_inicio: date | None = Query(default=None),
    fecha_fin: date | None = Query(default=None),
    estado: str | None = Query(default=None, pattern='^(emitida|pagada|anulada)$'),
    db: Session = Depends(get_db),
    current_user: Usuario = Depends(get_current_user),
):
    """Consulta las facturas generadas aplicando filtros de búsqueda."""
    consulta = db.query(Factura)

    if current_user.rol and current_user.rol.nombre == 'cliente':
        consulta = consulta.filter(Factura.cliente_id == current_user.id)
    elif cliente_id:
        consulta = consulta.filter(Factura.cliente_id == cliente_id)

    if numero_factura:
        consulta = consulta.filter(Factura.numero_factura.like(f'%{numero_factura}%'))
    if fecha_inicio:
        consulta = consulta.filter(Factura.fecha >= datetime.combine(fecha_inicio, time.min))
    if fecha_fin:
        consulta = consulta.filter(Factura.fecha <= datetime.combine(fecha_fin, time.max))
    if estado:
        consulta = consulta.filter(Factura.estado == estado)

    facturas = consulta.order_by(Factura.fecha.desc(), Factura.id.desc()).all()
    return {
        'invoices': [factura_a_dict(f) for f in facturas],
        'total': len(facturas),
        'facturado': round(sum(float(f.total or 0) for f in facturas), 2),
    }


@router.get('/{factura_id}')
def obtener_factura(
    factura_id: int,
    db: Session = Depends(get_db),
    current_user: Usuario = Depends(get_current_user),
):
    """Consulta una factura por su identificador."""
    factura = db.query(Factura).filter(Factura.id == factura_id).first()
    if factura is None:
        raise HTTPException(
            status_code=status.HTTP_404_NOT_FOUND,
            detail='Factura no encontrada.',
        )
    if current_user.rol and current_user.rol.nombre == 'cliente':
        if factura.cliente_id != current_user.id:
            raise HTTPException(
                status_code=status.HTTP_403_FORBIDDEN,
                detail='No tienes permiso para consultar esta factura.',
            )
    return {'invoice': factura_a_dict(factura)}


@router.get('/{factura_id}/pdf')
def descargar_factura_pdf(
    factura_id: int,
    db: Session = Depends(get_db),
    current_user: Usuario = Depends(get_current_user),
):
    """Genera y descarga la factura en formato PDF."""
    factura = db.query(Factura).filter(Factura.id == factura_id).first()
    if factura is None:
        raise HTTPException(
            status_code=status.HTTP_404_NOT_FOUND,
            detail='Factura no encontrada.',
        )
    if current_user.rol and current_user.rol.nombre == 'cliente':
        if factura.cliente_id != current_user.id:
            raise HTTPException(
                status_code=status.HTTP_403_FORBIDDEN,
                detail='No tienes permiso para descargar esta factura.',
            )

    buffer = factura_pdf(factura_a_dict(factura))
    nombre = f'factura_{factura.numero_factura}.pdf'
    return StreamingResponse(
        buffer,
        media_type='application/pdf',
        headers={'Content-Disposition': f'attachment; filename="{nombre}"'},
    )


@router.patch('/{factura_id}/estado')
def cambiar_estado_factura(
    factura_id: int,
    body: FacturaEstadoUpdate,
    db: Session = Depends(get_db),
    _: Usuario = Depends(require_roles(*ROLES_GESTION)),
):
    """Cambia el estado de una factura (emitida, pagada o anulada)."""
    factura = db.query(Factura).filter(Factura.id == factura_id).first()
    if factura is None:
        raise HTTPException(
            status_code=status.HTTP_404_NOT_FOUND,
            detail='Factura no encontrada.',
        )
    factura.estado = body.estado
    db.commit()
    return {'message': 'Estado de la factura actualizado.', 'estado': factura.estado}

router_dashboard:
"""
Rutas de Dashboards y estadísticas: /api/dashboard
(Requerimientos 10 al 15 del quinto avance)

- GET /api/dashboard/admin      → indicadores consolidados (administrador)
- GET /api/dashboard/empleado   → indicadores del área comercial (empleado)
- GET /api/dashboard/cliente    → resumen del cliente autenticado
- GET /api/dashboard/ventas     → gráficos de ventas con filtros
- GET /api/dashboard/filtros    → listas para los selects de filtrado

Toda la información se calcula desde la base de datos: el Frontend en React
NO tiene datos escritos a mano, únicamente consume estos endpoints.
"""
from datetime import date, datetime, time, timedelta

from fastapi import APIRouter, Depends, Query
from sqlalchemy import func
from sqlalchemy.orm import Session

from ..database import get_db
from ..models import (
    DetalleVenta,
    Factura,
    Pqr,
    Producto,
    Servicio,
    Usuario,
    Venta,
)
from ..security import get_current_user, require_roles

router = APIRouter(prefix='/api/dashboard', tags=['Dashboards'])

ROLES_GESTION = ('administrador', 'empleado')

MESES = [
    'Ene', 'Feb', 'Mar', 'Abr', 'May', 'Jun',
    'Jul', 'Ago', 'Sep', 'Oct', 'Nov', 'Dic',
]


def _num(valor) -> float:
    return float(valor or 0)


def _consultar_ventas(
    db: Session,
    fecha_inicio: date | None = None,
    fecha_fin: date | None = None,
    producto_id: int | None = None,
    servicio_id: int | None = None,
    estado: str | None = None,
    cliente_id: int | None = None,
):
    """Aplica los filtros de los Dashboards sobre las ventas."""
    consulta = db.query(Venta)

    if fecha_inicio:
        consulta = consulta.filter(Venta.fecha >= datetime.combine(fecha_inicio, time.min))
    if fecha_fin:
        consulta = consulta.filter(Venta.fecha <= datetime.combine(fecha_fin, time.max))
    if estado:
        consulta = consulta.filter(Venta.estado == estado)
    if cliente_id:
        consulta = consulta.filter(Venta.cliente_id == cliente_id)
    if producto_id or servicio_id:
        consulta = consulta.join(DetalleVenta, DetalleVenta.venta_id == Venta.id)
        if producto_id:
            consulta = consulta.filter(DetalleVenta.producto_id == producto_id)
        if servicio_id:
            consulta = consulta.filter(DetalleVenta.servicio_id == servicio_id)

    ventas = consulta.order_by(Venta.fecha.asc()).all()
    return list({v.id: v for v in ventas}.values())


def _agrupar(ventas, agrupacion: str, fecha_inicio: date | None, fecha_fin: date | None):
    """Construye las series de los gráficos (día, semana o mes)."""
    etapas: dict[str, float] = {}
    orden: list[str] = []

    def clave(venta):
        f = venta.fecha.date() if hasattr(venta.fecha, 'date') else venta.fecha
        if agrupacion == 'mes':
            return f"{MESES[f.month - 1]} {f.year}"
        if agrupacion == 'semana':
            inicio_semana = f - timedelta(days=f.weekday())
            return f"Sem {inicio_semana.strftime('%d/%m')}"
        return f.strftime('%d/%m')

    for venta in ventas:
        k = clave(venta)
        if k not in etapas:
            etapas[k] = 0.0
            orden.append(k)
        if venta.estado != 'anulada':
            etapas[k] += _num(venta.total)

    # Para el modo día se rellenan los días del rango (así el gráfico no queda con huecos)
    if agrupacion == 'dia' and fecha_inicio and fecha_fin:
        dia = fecha_inicio
        orden = []
        etapas = {}
        while dia <= fecha_fin:
            etiqueta = dia.strftime('%d/%m')
            orden.append(etiqueta)
            etapas[etiqueta] = 0.0
            dia += timedelta(days=1)
        for venta in ventas:
            f = venta.fecha.date() if hasattr(venta.fecha, 'date') else venta.fecha
            etiqueta = f.strftime('%d/%m')
            if venta.estado != 'anulada' and etiqueta in etapas:
                etapas[etiqueta] += _num(venta.total)

    return {
        'etiquetas': orden,
        'valores': [round(etapas[k], 2) for k in orden],
    }


def _productos_mas_vendidos(db: Session, limite: int = 5):
    filas = (
        db.query(
            DetalleVenta.descripcion,
            func.sum(DetalleVenta.cantidad).label('unidades'),
            func.sum(DetalleVenta.subtotal).label('valor'),
        )
        .join(Venta, Venta.id == DetalleVenta.venta_id)
        .filter(Venta.estado != 'anulada')
        .group_by(DetalleVenta.descripcion)
        .order_by(func.sum(DetalleVenta.cantidad).desc())
        .limit(limite)
        .all()
    )
    return [
        {
            'nombre': fila[0],
            'unidades': int(fila[1] or 0),
            'valor': round(_num(fila[2]), 2),
        }
        for fila in filas
    ]


def _series_comunes(db: Session, desde: date, hasta: date):
    ventas = _consultar_ventas(db, desde, hasta)
    return {
        'ventas_por_dia': _agrupar(ventas, 'dia', desde, hasta),
        'ventas_por_semana': _agrupar(ventas, 'semana', None, None),
        'ventas_por_mes': _agrupar(ventas, 'mes', None, None),
    }


@router.get('/admin')
def dashboard_admin(
    db: Session = Depends(get_db),
    _: Usuario = Depends(require_roles('administrador')),
):
    """Dashboard consolidado del administrador (indicadores + gráficos)."""
    total_usuarios = db.query(func.count(Usuario.id)).scalar() or 0
    usuarios_activos = (
        db.query(func.count(Usuario.id)).filter(Usuario.estado == 'activo').scalar() or 0
    )
    total_productos = db.query(func.count(Producto.id)).scalar() or 0
    productos_stock_bajo = (
        db.query(func.count(Producto.id))
        .filter(Producto.estado == 'activo', Producto.stock <= 5)
        .scalar()
        or 0
    )
    total_servicios = db.query(func.count(Servicio.id)).scalar() or 0

    ventas = db.query(Venta).all()
    ventas_validas = [v for v in ventas if v.estado != 'anulada']
    total_ventas = len(ventas)
    facturacion = round(sum(_num(v.total) for v in ventas_validas), 2)
    impuestos = round(sum(_num(v.impuestos) for v in ventas_validas), 2)

    total_facturas = db.query(func.count(Factura.id)).scalar() or 0

    pqr_total = db.query(func.count(Pqr.id)).scalar() or 0
    pqr_pendientes = (
        db.query(func.count(Pqr.id)).filter(Pqr.estado == 'pendiente').scalar() or 0
    )
    pqr_en_proceso = (
        db.query(func.count(Pqr.id)).filter(Pqr.estado == 'en_proceso').scalar() or 0
    )

    hoy = date.today()
    desde = hoy - timedelta(days=13)

    return {
        'indicadores': {
            'total_usuarios': total_usuarios,
            'usuarios_activos': usuarios_activos,
            'total_productos': total_productos,
            'productos_stock_bajo': productos_stock_bajo,
            'total_servicios': total_servicios,
            'total_ventas': total_ventas,
            'facturacion_total': facturacion,
            'impuestos_total': impuestos,
            'total_facturas': total_facturas,
            'pqr_total': pqr_total,
            'pqr_pendientes': pqr_pendientes,
            'pqr_en_proceso': pqr_en_proceso,
        },
        'graficos': _series_comunes(db, desde, hoy),
        'top_productos': _productos_mas_vendidos(db),
        'por_estado': _por_estado(ventas),
    }


@router.get('/empleado')
def dashboard_empleado(
    db: Session = Depends(get_db),
    _: Usuario = Depends(require_roles(*ROLES_GESTION)),
):
    """Dashboard del empleado: información comercial y de PQR."""
    total_productos = db.query(func.count(Producto.id)).scalar() or 0
    productos_stock_bajo = (
        db.query(func.count(Producto.id))
        .filter(Producto.estado == 'activo', Producto.stock <= 5)
        .scalar()
        or 0
    )
    total_servicios = db.query(func.count(Servicio.id)).scalar() or 0

    hoy = date.today()
    ventas_hoy = (
        db.query(Venta)
        .filter(
            Venta.fecha >= datetime.combine(hoy, time.min),
            Venta.fecha <= datetime.combine(hoy, time.max),
            Venta.estado != 'anulada',
        )
        .all()
    )
    ventas = db.query(Venta).all()
    ventas_validas = [v for v in ventas if v.estado != 'anulada']

    pqr_pendientes = (
        db.query(func.count(Pqr.id)).filter(Pqr.estado == 'pendiente').scalar() or 0
    )
    pqr_en_proceso = (
        db.query(func.count(Pqr.id)).filter(Pqr.estado == 'en_proceso').scalar() or 0
    )

    desde = hoy - timedelta(days=13)
    return {
        'indicadores': {
            'total_productos': total_productos,
            'productos_stock_bajo': productos_stock_bajo,
            'total_servicios': total_servicios,
            'ventas_hoy': len(ventas_hoy),
            'facturacion_hoy': round(sum(_num(v.total) for v in ventas_hoy), 2),
            'total_ventas': len(ventas),
            'facturacion_total': round(sum(_num(v.total) for v in ventas_validas), 2),
            'pqr_pendientes': pqr_pendientes,
            'pqr_en_proceso': pqr_en_proceso,
        },
        'graficos': _series_comunes(db, desde, hoy),
        'top_productos': _productos_mas_vendidos(db),
        'por_estado': _por_estado(ventas),
    }


@router.get('/cliente')
def dashboard_cliente(
    db: Session = Depends(get_db),
    current_user: Usuario = Depends(get_current_user),
):
    """Dashboard del cliente: sus compras, facturación y PQR."""
    ventas = (
        db.query(Venta)
        .filter(Venta.cliente_id == current_user.id)
        .order_by(Venta.fecha.asc())
        .all()
    )
    validas = [v for v in ventas if v.estado != 'anulada']
    facturas = (
        db.query(Factura).filter(Factura.cliente_id == current_user.id).all()
    )
    pqr = db.query(Pqr).filter(Pqr.usuario_id == current_user.id).all()

    hoy = date.today()
    desde = hoy - timedelta(days=29)
    return {
        'indicadores': {
            'total_compras': len(ventas),
            'total_gastado': round(sum(_num(v.total) for v in validas), 2),
            'total_facturas': len(facturas),
            'facturado': round(sum(_num(f.total) for f in facturas), 2),
            'pqr_total': len(pqr),
            'pqr_pendientes': sum(1 for p in pqr if p.estado in {'pendiente', 'en_proceso'}),
        },
        'graficos': {
            'compras_por_dia': _agrupar(validas, 'dia', desde, hoy),
            'compras_por_mes': _agrupar(validas, 'mes', None, None),
        },
        'ultimas_compras': [
            {
                'id': v.id,
                'numero_venta': v.numero_venta,
                'total': _num(v.total),
                'estado': v.estado,
                'fecha': v.fecha,
            }
            for v in reversed(ventas[-5:])
        ],
    }


@router.get('/ventas')
def dashboard_ventas(
    fecha_inicio: date | None = Query(default=None),
    fecha_fin: date | None = Query(default=None),
    producto_id: int | None = Query(default=None),
    servicio_id: int | None = Query(default=None),
    estado: str | None = Query(default=None, pattern='^(pendiente|pagada|anulada)$'),
    cliente_id: int | None = Query(default=None),
    agrupacion: str = Query(default='dia', pattern='^(dia|semana|mes)$'),
    db: Session = Depends(get_db),
    _: Usuario = Depends(require_roles(*ROLES_GESTION)),
):
    """Gráficos de ventas filtrables por fecha, producto, servicio, estado y cliente."""
    ventas = _consultar_ventas(
        db, fecha_inicio, fecha_fin, producto_id, servicio_id, estado, cliente_id
    )
    validas = [v for v in ventas if v.estado != 'anulada']
    return {
        'indicadores': {
            'total_ventas': len(ventas),
            'facturacion': round(sum(_num(v.total) for v in validas), 2),
            'ticket_promedio': round(
                (sum(_num(v.total) for v in validas) / len(validas)) if validas else 0, 2
            ),
            'unidades_vendidas': sum(
                d.cantidad for v in validas for d in v.detalles
            ),
        },
        'series': _agrupar(ventas, agrupacion, fecha_inicio, fecha_fin),
        'por_estado': _por_estado(ventas),
        'top_productos': _productos_mas_vendidos(db),
    }


def _por_estado(ventas):
    return [
        {
            'estado': estado,
            'cantidad': sum(1 for v in ventas if v.estado == estado),
        }
        for estado in ('pendiente', 'pagada', 'anulada')
    ]


@router.get('/filtros')
def filtros_dashboard(
    db: Session = Depends(get_db),
    _: Usuario = Depends(require_roles(*ROLES_GESTION)),
):
    """Listas necesarias para los filtros de los Dashboards."""
    return {
        'productos': [
            {'id': p.id, 'nombre': p.nombre, 'precio': float(p.precio or 0)}
            for p in db.query(Producto).order_by(Producto.nombre).all()
        ],
        'servicios': [
            {'id': s.id, 'nombre': s.nombre, 'precio': float(s.precio or 0)}
            for s in db.query(Servicio).order_by(Servicio.nombre).all()
        ],
        'clientes': [
            {'id': u.id, 'nombre': f'{u.nombre} {u.apellido}'}
            for u in db.query(Usuario).order_by(Usuario.nombre).all()
        ],
        'estados': ['pendiente', 'pagada', 'anulada'],
    }

router_pqr:
"""
Rutas de PQR — Peticiones, Quejas y Reclamos: /api/pqr
(Requerimiento 16 del quinto avance)

- POST   /api/pqr             → el cliente registra una PQR
- GET    /api/pqr             → listar PQR (el cliente solo ve las suyas)
- GET    /api/pqr/{id}        → consultar una PQR y su estado
- PATCH  /api/pqr/{id}        → gestionar (estado, respuesta) — admin o empleado
- DELETE /api/pqr/{id}        → eliminar una PQR (solo admin)
"""
from fastapi import APIRouter, Depends, HTTPException, Query, status
from sqlalchemy.orm import Session

from ..database import get_db
from ..models import Pqr, Usuario
from ..schemas import PqrCreate, PqrUpdate
from ..security import get_current_user, require_roles
from ..utils.serializadores import pqr_a_dict

router = APIRouter(prefix='/api/pqr', tags=['PQR'])

ROLES_GESTION = ('administrador', 'empleado')


def _es_cliente(usuario: Usuario) -> bool:
    return usuario.rol is not None and usuario.rol.nombre == 'cliente'


@router.post('', status_code=status.HTTP_201_CREATED)
def registrar_pqr(
    body: PqrCreate,
    db: Session = Depends(get_db),
    current_user: Usuario = Depends(get_current_user),
):
    """Registra una petición, queja o reclamo asociada al usuario autenticado."""
    pqr = Pqr(
        usuario_id=current_user.id,
        tipo=body.tipo,
        asunto=body.asunto,
        descripcion=body.descripcion,
        estado='pendiente',
    )
    db.add(pqr)
    db.commit()
    db.refresh(pqr)
    return {
        'message': 'Solicitud registrada exitosamente. Queda en estado pendiente.',
        'pqr': pqr_a_dict(pqr),
    }


@router.get('')
def listar_pqr(
    estado: str | None = Query(default=None, pattern='^(pendiente|en_proceso|respondida|cerrada)$'),
    tipo: str | None = Query(default=None, pattern='^(peticion|queja|reclamo)$'),
    usuario_id: int | None = Query(default=None),
    db: Session = Depends(get_db),
    current_user: Usuario = Depends(get_current_user),
):
    """Lista las PQR. El cliente únicamente consulta las propias."""
    consulta = db.query(Pqr)

    if _es_cliente(current_user):
        consulta = consulta.filter(Pqr.usuario_id == current_user.id)
    elif usuario_id:
        consulta = consulta.filter(Pqr.usuario_id == usuario_id)

    if estado:
        consulta = consulta.filter(Pqr.estado == estado)
    if tipo:
        consulta = consulta.filter(Pqr.tipo == tipo)

    solicitudes = consulta.order_by(Pqr.fecha_creacion.desc(), Pqr.id.desc()).all()
    return {
        'pqr': [pqr_a_dict(p) for p in solicitudes],
        'total': len(solicitudes),
        'pendientes': sum(1 for p in solicitudes if p.estado == 'pendiente'),
        'en_proceso': sum(1 for p in solicitudes if p.estado == 'en_proceso'),
    }


@router.get('/{pqr_id}')
def obtener_pqr(
    pqr_id: int,
    db: Session = Depends(get_db),
    current_user: Usuario = Depends(get_current_user),
):
    """Consulta el estado de una PQR."""
    pqr = db.query(Pqr).filter(Pqr.id == pqr_id).first()
    if pqr is None:
        raise HTTPException(
            status_code=status.HTTP_404_NOT_FOUND,
            detail='Solicitud PQR no encontrada.',
        )
    if _es_cliente(current_user) and pqr.usuario_id != current_user.id:
        raise HTTPException(
            status_code=status.HTTP_403_FORBIDDEN,
            detail='No tienes permiso para consultar esta solicitud.',
        )
    return {'pqr': pqr_a_dict(pqr)}


@router.patch('/{pqr_id}')
def gestionar_pqr(
    pqr_id: int,
    body: PqrUpdate,
    db: Session = Depends(get_db),
    current_user: Usuario = Depends(require_roles(*ROLES_GESTION)),
):
    """Gestiona una PQR: cambia el estado y registra la respuesta del equipo."""
    pqr = db.query(Pqr).filter(Pqr.id == pqr_id).first()
    if pqr is None:
        raise HTTPException(
            status_code=status.HTTP_404_NOT_FOUND,
            detail='Solicitud PQR no encontrada.',
        )

    datos = body.model_dump(exclude_unset=True, exclude_none=True)
    for campo, valor in datos.items():
        setattr(pqr, campo, valor)

    if body.estado in {'respondida', 'cerrada'} and not pqr.respuesta:
        raise HTTPException(
            status_code=status.HTTP_400_BAD_REQUEST,
            detail='Debes registrar una respuesta antes de marcar la PQR como respondida o cerrada.',
        )

    db.commit()
    db.refresh(pqr)
    return {
        'message': 'Solicitud PQR actualizada exitosamente.',
        'pqr': pqr_a_dict(pqr),
    }


@router.delete('/{pqr_id}')
def eliminar_pqr(
    pqr_id: int,
    db: Session = Depends(get_db),
    _: Usuario = Depends(require_roles('administrador')),
):
    """Elimina una solicitud PQR (solo administrador)."""
    pqr = db.query(Pqr).filter(Pqr.id == pqr_id).first()
    if pqr is None:
        raise HTTPException(
            status_code=status.HTTP_404_NOT_FOUND,
            detail='Solicitud PQR no encontrada.',
        )
    db.delete(pqr)
    db.commit()
    return {'message': 'Solicitud PQR eliminada exitosamente.'}

router_chat:
"""
Rutas del Chatbot: /api/chat  (Requerimientos 17 y 18 del quinto avance)

- GET  /api/chat/info                 → estado del chatbot (IA activa o local)
- POST /api/chat                      → enviar un mensaje y recibir la respuesta
- GET  /api/chat/conversaciones       → historial de conversaciones
- GET  /api/chat/conversaciones/{id}  → mensajes de una conversación

El chatbot funciona para visitantes anónimos y para usuarios autenticados
(el contexto del usuario se usa para personalizar la atención).
"""
from fastapi import APIRouter, Depends, HTTPException, status
from sqlalchemy.orm import Session

from ..config import IA_ENABLED, IA_MODEL
from ..database import get_db
from ..models import Conversacion, Mensaje, Usuario
from ..schemas import ChatRequest, ChatResponse
from ..security import get_current_user, get_optional_user
from ..utils.ia import MENSAJE_BIENVENIDA, SUGERENCIAS, responder

router = APIRouter(prefix='/api/chat', tags=['Chatbot'])


def _conversacion_a_dict(conversacion: Conversacion) -> dict:
    return {
        'id': conversacion.id,
        'usuario_id': conversacion.usuario_id,
        'titulo': conversacion.titulo,
        'fecha_creacion': conversacion.fecha_creacion,
        'mensajes': [
            {
                'id': m.id,
                'rol': m.rol,
                'contenido': m.contenido,
                'fecha_creacion': m.fecha_creacion,
            }
            for m in conversacion.mensajes
        ],
    }


@router.get('/info')
def info_chatbot():
    """Información de bienvenida del chatbot y estado de la integración con IA."""
    return {
        'bot': 'TechBot',
        'mensaje': MENSAJE_BIENVENIDA,
        'sugerencias': SUGERENCIAS,
        'ia_activa': IA_ENABLED,
        'modelo': IA_MODEL if IA_ENABLED else 'motor local de reglas',
    }


@router.post('', response_model=ChatResponse)
def enviar_mensaje(
    body: ChatRequest,
    db: Session = Depends(get_db),
    current_user: Usuario | None = Depends(get_optional_user),
):
    """
    Procesa el mensaje del usuario, lo guarda en la conversación y devuelve la
    respuesta generada por la IA (o por el motor local si no hay API Key).
    """
    conversacion = None
    if body.conversacion_id:
        conversacion = (
            db.query(Conversacion)
            .filter(Conversacion.id == body.conversacion_id)
            .first()
        )
        if conversacion is None:
            raise HTTPException(
                status_code=status.HTTP_404_NOT_FOUND,
                detail='Conversación no encontrada.',
            )
        if (
            current_user is not None
            and conversacion.usuario_id is not None
            and conversacion.usuario_id != current_user.id
            and (current_user.rol is None or current_user.rol.nombre == 'cliente')
        ):
            raise HTTPException(
                status_code=status.HTTP_403_FORBIDDEN,
                detail='No tienes permiso para continuar esta conversación.',
            )

    if conversacion is None:
        conversacion = Conversacion(
            usuario_id=current_user.id if current_user else None,
            titulo=body.mensaje[:60],
        )
        db.add(conversacion)
        db.flush()

    historial = [
        {
            'role': 'assistant' if m.rol == 'asistente' else 'user',
            'content': m.contenido,
        }
        for m in conversacion.mensajes[-8:]
    ]

    respuesta, fuente = responder(body.mensaje, historial, db)

    db.add(Mensaje(conversacion_id=conversacion.id, rol='usuario', contenido=body.mensaje))
    db.add(Mensaje(conversacion_id=conversacion.id, rol='asistente', contenido=respuesta))
    db.commit()

    return ChatResponse(
        conversacion_id=conversacion.id,
        respuesta=respuesta,
        fuente=fuente,
        sugerencias=SUGERENCIAS,
    )


@router.get('/conversaciones')
def listar_conversaciones(
    db: Session = Depends(get_db),
    current_user: Usuario = Depends(get_current_user),
):
    """Historial de conversaciones del chatbot (el cliente ve las propias)."""
    consulta = db.query(Conversacion)
    if current_user.rol and current_user.rol.nombre == 'cliente':
        consulta = consulta.filter(Conversacion.usuario_id == current_user.id)

    conversaciones = consulta.order_by(Conversacion.fecha_creacion.desc()).all()
    return {
        'conversations': [
            {
                'id': c.id,
                'titulo': c.titulo,
                'fecha_creacion': c.fecha_creacion,
                'mensajes': len(c.mensajes),
            }
            for c in conversaciones
        ]
    }


@router.get('/conversaciones/{conversacion_id}')
def obtener_conversacion(
    conversacion_id: int,
    db: Session = Depends(get_db),
    current_user: Usuario = Depends(get_current_user),
):
    """Mensajes de una conversación del chatbot."""
    conversacion = (
        db.query(Conversacion).filter(Conversacion.id == conversacion_id).first()
    )
    if conversacion is None:
        raise HTTPException(
            status_code=status.HTTP_404_NOT_FOUND,
            detail='Conversación no encontrada.',
        )
    if (
        current_user.rol
        and current_user.rol.nombre == 'cliente'
        and conversacion.usuario_id not in {None, current_user.id}
    ):
        raise HTTPException(
            status_code=status.HTTP_403_FORBIDDEN,
            detail='No tienes permiso para consultar esta conversación.',
        )
    return {'conversation': _conversacion_a_dict(conversacion)}

api_js:
// URL base de la API y helpers para las peticiones al backend FastAPI.
//
// Quinto avance: la URL se puede configurar con la variable de entorno
// VITE_API_URL (útil al desplegar en Railway, Render, Vercel, etc.).
// En desarrollo local se usa http://localhost:8000/api.

const API_URL = import.meta.env.VITE_API_URL || 'http://localhost:8000/api'

export const getAuthHeaders = (token) => ({
  'Content-Type': 'application/json',
  Authorization: `Bearer ${token}`,
})

/**
 * Realiza una petición a la API y devuelve el JSON.
 * Lanza un Error con el mensaje del backend cuando la respuesta no es exitosa.
 */
export const apiFetch = async (path, { token, method = 'GET', body, ...rest } = {}) => {
  const res = await fetch(`${API_URL}${path}`, {
    method,
    headers: token ? getAuthHeaders(token) : { 'Content-Type': 'application/json' },
    body: body ? JSON.stringify(body) : undefined,
    ...rest,
  })

  const tipo = res.headers.get('content-type') || ''
  const data = tipo.includes('application/json') ? await res.json() : null

  if (!res.ok) {
    const detalle = data?.detail
    const mensaje =
      typeof detalle === 'string'
        ? detalle
        : Array.isArray(detalle)
          ? detalle.map((d) => d.msg).join(' ')
          : data?.message || `Error ${res.status} al consultar la API.`
    throw new Error(mensaje)
  }
  return data
}

/**
 * Descarga un archivo (PDF o Excel) generado por el backend.
 * Devuelve la URL temporal del objeto y el nombre sugerido del archivo.
 */
export const descargarArchivo = async (path, token, nombrePorDefecto = 'documento') => {
  const res = await fetch(`${API_URL}${path}`, {
    headers: token ? { Authorization: `Bearer ${token}` } : {},
  })
  if (!res.ok) {
    throw new Error('No se pudo generar el documento.')
  }

  const disposicion = res.headers.get('content-disposition') || ''
  const coincidencia = disposicion.match(/filename="?([^"]+)"?/)
  const nombre = coincidencia ? coincidencia[1] : nombrePorDefecto

  const blob = await res.blob()
  const url = window.URL.createObjectURL(blob)
  const enlace = document.createElement('a')
  enlace.href = url
  enlace.download = nombre
  document.body.appendChild(enlace)
  enlace.click()
  enlace.remove()
  window.URL.revokeObjectURL(url)
  return nombre
}

export default API_URL

