      {lineas.map((p) => {
        const y = padding.top + alturaArea - p * alturaArea
        return (
          <g key={p}>
            <line
              x1={padding.left}
              y1={y}
              x2={ancho - padding.right}
              y2={y}
              stroke="currentColor"
              strokeOpacity="0.15"
              strokeDasharray="4 4"
            />
            <text
              x={padding.left - 8}
              y={y + 4}
              textAnchor="end"
              className="fill-slate-500 dark:fill-slate-400"
              style={{ fontSize: 10 }}
            >
              {formato(Math.round(escala * p))}
            </text>
          </g>
        )
      })}

      <polygon points={area} fill={`url(#area-${color.replace('#', '')})`} />
      <polyline
        points={linea}
        fill="none"
        stroke={color}
